+    if (n <= 0) return;
+
+    unsigned int num_threads = std::thread::hardware_concurrency();
+    if (num_threads == 0 || num_threads > 16) num_threads = 10;
+    if (num_threads > (unsigned int)n) num_threads = (unsigned int)n;
+
+    // Single thread for tiny matrices (thread creation overhead dominates)
+    if (num_threads < 2 || n < 32) {
+        matmul_row_block(n, A, B, C, 0, n);
